    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The 2 stripe is the barrier. Move the small object toward it and
    # mark the object's far edge with an 8 stripe.
    barriers = [c for c in range(w) if all(grid[r][c] == 2 for r in range(h))]
    horizontal = bool(barriers)
    if horizontal:
        axis = 1
        b = barriers[0]
        line = None
    else:
        barriers = [r for r in range(h) if all(v == 2 for v in grid[r])]
        if not barriers:
            return out
        axis = 0
        b = barriers[0]
    counts = {}
    for row in grid:
        for v in row:
            if v != 2:
                counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    obj = {(r,c) for r in range(h) for c in range(w) if grid[r][c] not in (2,bg)}
    if not obj:
        return out
    coords = [r if axis == 0 else c for r,c in obj]
    lo, hi = min(coords), max(coords)
    # Translate toward the stripe until one cell remains between object and stripe.
    if b > hi:
        delta = b - hi - 1
        direction = 1
    elif b < lo:
        delta = lo - b - 1
        direction = -1
    else:
        delta, direction = 0, 1
    moved = {(r + (delta*direction if axis == 0 else 0),
              c + (delta*direction if axis == 1 else 0)) for r,c in obj}
    # Clear old object locations, then place translated object.
    for r,c in obj:
        out[r][c] = bg
    for r,c in moved:
        out[r][c] = grid[next((rr for rr,cc in obj if cc == c-delta*direction),r)][c-delta*direction] if axis == 1 else grid[r-delta*direction][c]
    # Draw the 8 stripe just beyond the translated object, away from barrier.
    newcoords = [r if axis == 0 else c for r,c in moved]
    edge = min(newcoords) if b > max(newcoords) else max(newcoords)
    stripe = edge - 1 if b > max(newcoords) else edge + 1
    if axis == 0 and 0 <= stripe < h:
        out[stripe] = [8] * w
    elif axis == 1 and 0 <= stripe < w:
        for r in range(h): out[r][stripe] = 8
